export function parseAnnotations(d,raw){const a=raw===null?[]:JSON.parse(raw);if(!Array.isArray(a)||new Set(a.map(x=>x.id)).size!==a.length)throw Error('Invalid annotation collection');a.forEach(x=>validateAnnotation(d,x));return a;}
